s:ui-execute-js.script:
var ths = document.querySelectorAll('table.webutils-search-results thead th');
for(var i = 0; i < ths.length; i++) {
	if((ths[i].textContent || '').indexOf('Description') >= 0) {
		return true;
	}
}
return false;

var ths = document.querySelectorAll('table.webutils-search-results thead th');
var statusIdx = -1, catIdx = -1;
for(var i = 0; i < ths.length; i++) {
	var t = (ths[i].textContent || '').trim();
	if(t.indexOf('Status') >= 0) { statusIdx = i; }
	if(t.indexOf('Category') >= 0) { catIdx = i; }
}
return statusIdx >= 0 && catIdx >= 0 && statusIdx < catIdx;
